# Let's write our scorer and compare
def score_phq9(row):
    items = [f'phq9_{i}' for i in range(1, 10)]
    vals = []
    skipped = 0
    for it in items:
        val = row[it]
        if pd.isna(val) or val == -9 or val < 0 or val > 3:
            skipped += 1
        else:
            vals.append(val)

    # Self harm flag
    sh_val = row['phq9_9']
    if pd.isna(sh_val) or sh_val == -9 or sh_val < 0 or sh_val > 3:
        sh_flag = None
    else:
        sh_flag = (sh_val > 0)

    if skipped >= 2:
        return pd.Series({'phq9_total': np.nan, 'phq9_band': np.nan, 'phq9_prorated': np.nan, 'phq9_self_harm_flag': sh_flag})
    elif skipped == 1:
        # scale up: sum * 9 / 8, round half up
        from decimal import Decimal, ROUND_HALF_UP
        s = sum(vals)
        scaled = Decimal(s * 9) / Decimal(8)
        total = int(scaled.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = sum(vals)
        prorated = False

    # band
    if total <= 4:
        band = "none-minimal"
    elif total <= 9:
        band = "mild"
    elif total <= 14:
        band = "moderate"
    elif total <= 19:
        band = "moderately severe"
    else:
        band = "severe"

    return pd.Series({'phq9_total': float(total), 'phq9_band': band, 'phq9_prorated': prorated, 'phq9_self_harm_flag': sh_flag})

