        else:
            vals.append(val)

    if skipped >= 2:
        return pd.Series({'gad7_total': np.nan, 'gad7_band': np.nan, 'gad7_prorated': np.nan})
    elif skipped == 1:
        from decimal import Decimal, ROUND_HALF_UP
        s = sum(vals)
        scaled = Decimal(s * 7) / Decimal(6)
        total = int(scaled.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = sum(vals)
        prorated = False

    if total <= 4:
        band = "minimal"
    elif total <= 9:
        band = "mild"
    elif total <= 14:
        band = "moderate"
    else:
        band = "severe"

    return pd.Series({'gad7_total': float(total), 'gad7_band': band, 'gad7_prorated': prorated})

def score_rses(row):
    items = [f'rses_{i}' for i in range(1, 11)]
    rev_items = [3, 5, 8, 9, 10]
    vals = []
    skipped = 0
    for i in range(1, 11):
        it = f'rses_{i}'
        val = row[it]
        if pd.isna(val) or val == -9 or val < 0 or val > 3:
            skipped += 1
        else:
            if i in rev_items:
                vals.append(3 - val)
            else:
                vals.append(val)

    if skipped >= 2:
        return pd.Series({'rses_total': np.nan, 'rses_prorated': np.nan})
    elif skipped == 1:
        from decimal import Decimal, ROUND_HALF_UP
        s = sum(vals)
        scaled = Decimal(s * 10) / Decimal(9)
        total = int(scaled.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
