    if not match:
        # count mismatches
        diff = merged[col_pipe] != merged[col_my]
        # handle NaNs correctly
        diff = ~((merged[col_pipe].isna() & merged[col_my].isna()) | (merged[col_pipe] == merged[col_my]))
        print(f"Mismatch in {col}: {diff.sum()} rows")
        if diff.sum() > 0:
            print(merged[diff][['respondent_id', col_pipe, col_my]].head())
    else:
        print(f"Match: {col}")
