        items = [f'gad7_{i}' for i in range(1, 7)]
    elif variant == 'items_2_7':
        items = [f'gad7_{i}' for i in range(2, 8)]
    elif variant == 'phq9_items': # wait
        items = [f'phq9_{i}' for i in range(1, 8)] # wait
    elif variant == 'off_by_one_index':
        # what if items are 0 to 6 instead of 1 to 7? (e.g. gad7_0 to gad7_6)
        pass

    vals = []
    skipped = 0
    for it in items:
        val = row[it]
        if pd.isna(val) or val == -9 or val < 0 or val > 3:
            skipped += 1
        else:
            vals.append(val)
    if skipped >= 2:
        return np.nan
    elif skipped == 1:
        s = sum(vals)
        from decimal import Decimal, ROUND_HALF_UP
        scaled = Decimal(s * len(items)) / Decimal(len(items)-1)
        return int(scaled.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    else:
        return sum(vals)

for var in ['items_1_6', 'items_2_7']:
